import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
	public static void main (String[] args) throws java.lang.Exception
	{
        Scanner sc = new Scanner(System.in);
        int t = sc.nextInt();
        while(t-->0){
            int n = sc.nextInt();
            int z = 3*n;
            int[] x = new int[z];
            for(int i=0; i<z; i++) x[i]=sc.nextInt();
            Arrays.sort(x);
            
            long[] p = new long[z+1];
            for(int i=0; i<z; i++){
                p[i+1]=p[i]+x[z-1-i];
            }
            
            long ans=0;
            for(int a=0; a<=n; a++){
                int l=0, r=n-a;
                while(l<r){
                    int m=(l+r)/2;
                    int b1 = a+2*m;
                    int c1 = 3*n-2*a-m;
                    long v1 = 2*p[a] + p[b1] + 3*p[c1];
                    
                    int b2 = a+2*(m+1);
                    int c2 = 3*n - 2*a - (m+1);
                    long v2 = 2*p[a] + p[b2] + 3*p[c2];
                    
                    if(v2>v1) l=m+1;
                    else r=m;
                }
                int b = a+2*l;
                int c = 3*n - 2*a - l;
                long cur = 2*p[a] + p[b] + 3*p[c];
                
                ans = Math.max(ans, cur);
            }
            System.out.println(ans);
        }
	}
}
